insert into learning_outcomes (id, curriculum_version_id, grade, subject_code, code, title, description, theme, unit, outcome_type, sort_order, source_page, source_note) values
  ('a42cac23-d366-54ba-b8f4-b2df5f3cd5dc', '896ab944-bcb0-5ddf-9bbd-4fc206d1bc20', 10, 'FEL', 'FEL.10.1.1', 'Felsefenin anlamını ve gelişim sürecini sorgulayabilme', 'a) Felsefenin anlamını merak eder.
b) Felsefenin ortak bir tanımının olup olmamasına şüphe ile yaklaşır.
c) Felsefenin anlamına yönelik farklı görüşler üzerine derinlemesine düşünür.
ç) Felsefi düşüncenin ortaya çıkışı, tarihsel dönemlerinin genel özellikleri ve dünyadaki felsefe gelenekleri üzerine derinlemesine düşünür.', null, 'FEL.10.1', 'OGRENME_CIKTISI', 1, 14, null),
  ('19fa904e-82df-5160-87a3-8eae7aa89070', '896ab944-bcb0-5ddf-9bbd-4fc206d1bc20', 10, 'FEL', 'FEL.10.1.2', 'Felsefenin özelliklerini, farklı alanlarla ilişkisini ve işlevini sorgulayabilme', 'a) Felsefi düşüncenin özellikleri üzerine derinlemesine düşünür.
b) Felsefi soruların temel özelliklerini ifade ederek felsefi soru sorar.
c) Felsefenin bilim, din ve sanat alanlarıyla ilişkisine eleştirel yaklaşır.
ç) Felsefenin bireysel ve toplumsal işlevlerini tartışır.', null, 'FEL.10.1', 'OGRENME_CIKTISI', 2, 14, null),
  ('f5fe4176-b726-5489-ba17-6b33975f74fb', '896ab944-bcb0-5ddf-9bbd-4fc206d1bc20', 10, 'FEL', 'FEL.10.2.1', 'Mantık ve argümantasyonda kullanılan temel kavramları yorumlayabilme', 'a) Düşünme ve dil ilişkisini mantık açısından inceler.
b) Mantık ve argümantasyonla ilgili kavramları örneklendirerek inceler.
c) Günlük dilde verilen argümanları mantığın biçimsel diline dönüştürerek yeniden ifade eder.', null, 'FEL.10.2', 'OGRENME_CIKTISI', 3, 18, null),
  ('5af42d49-681f-5d85-966e-4c662213a47c', '896ab944-bcb0-5ddf-9bbd-4fc206d1bc20', 10, 'FEL', 'FEL.10.3.1', 'Varlık felsefesinin konusunu, kavramlarını ve problemlerini muhakeme edebilme', 'a) Varlık felsefesinin konusunu ve temel kavramlarını açıklar.
b) Varlık felsefesinin temel problemlerini açıklar.
c) Varlık felsefesinin temel problemlerine yönelik düşünce ve argümanları değerlendirir.
ç) Varlık felsefesiyle ilgili metinlerde yer alan kavram, problem ve argümanları inceler.', null, 'FEL.10.3', 'OGRENME_CIKTISI', 4, 21, null),
  ('ca62e23d-ad96-5662-9819-1f9634ce85fa', '896ab944-bcb0-5ddf-9bbd-4fc206d1bc20', 10, 'FEL', 'FEL.10.4.1', 'Bilgi felsefesinin konusunu, kavramlarını ve problemlerini muhakeme edebilme', 'a) Bilgi felsefesinin konusunu ve temel kavramlarını açıklar.
b) Bilgi felsefesinin temel problemlerini açıklar.
c) Bilgi felsefesinin temel problemlerine yönelik düşünce ve argümanları değerlendirir.
ç) Bilgi felsefesiyle ilgili metinlerde yer alan kavram, problem ve argümanları inceler.', null, 'FEL.10.4', 'OGRENME_CIKTISI', 5, 24, null),
