insert into learning_outcomes (id, curriculum_version_id, grade, subject_code, code, title, description, theme, unit, outcome_type, sort_order, source_page, source_note) values
  ('e7443fe1-5d17-5959-b449-86fe1b22e3a1', '45f7db83-3464-5207-904e-b89115b1ef0d', 9, 'BIY', 'BİY.9.1.1', 'Biyolojideki dönüm noktalarının insan hayatına katkılarını sorgulayabilme', 'a) Biyolojideki dönüm noktalarının insan hayatına katkılarını belirtir.
b) Biyolojideki dönüm noktalarının insan hayatına katkılarıyla ilgili sorular sorar.
c) Biyolojideki dönüm noktalarının insan hayatına katkılarıyla ilgili bilgi toplar.
ç) Biyolojideki dönüm noktalarının insan hayatına katkılarıyla ilgili topladığı bilgilerin doğruluğunu değerlendirir.
d) Biyolojideki dönüm noktalarının insan hayatına katkılarıyla ilgili topladığı bilgiler üzerinden çıkarım yapar.', null, 'BİY.9.1', 'OGRENME_CIKTISI', 1, 16, null),
  ('30f243c9-b40a-5ab8-b900-670b53740e8a', '45f7db83-3464-5207-904e-b89115b1ef0d', 9, 'BIY', 'BİY.9.1.2', 'Bilimsel araştırma süreçlerinde bilimin doğasını yorumlayabilme', 'a) Bilimsel araştırma süreçlerinde bilimin doğasının özelliklerini inceler.
b) Bilimsel araştırma süreçlerinde bilimin doğasıyla ilgili elde ettiği bilgileri bağlamdan kopmadan dönüştürür.
