insert into learning_outcomes (id, curriculum_version_id, grade, subject_code, code, title, description, theme, unit, outcome_type, sort_order, source_page, source_note) values
  ('5e0023b4-3203-59bc-9004-2717651cb3a1', '07594541-2ac4-571e-b130-d376236e8d64', 9, 'TAR', 'TAR.9.1.1', 'Tarih öğrenmenin bireye ve topluma faydalarını yorumlayabilme VE SÜREÇ BİLEŞENLERİ', 'a) Tarih öğrenmenin bireye ve topluma faydalarını kaynaklardan inceler.
b) Tarih öğrenmenin bireye ve topluma faydalarıyla ilgili incelediği kaynakları bağlamından kopmadan özetler.
c) Tarih öğrenmenin bireye ve topluma faydalarını kendi cümleleriyle açıklar.', null, 'TAR.9.1', 'OGRENME_CIKTISI', 1, 17, null),
  ('ac845434-f321-52e3-867c-ae83e72914c0', '07594541-2ac4-571e-b130-d376236e8d64', 9, 'TAR', 'TAR.9.1.2', 'Tarihin doğasını farklı kaynaklar üzerinden inceleyebilme', 'a) Farklı kaynaklardan tarihin doğasına ilişkin temel bilgileri tespit eder.
