  ('3863303f-4143-5336-a619-7f62898b2f4a', 'b6eccff7-7867-5649-a250-9d7f4848bac1', 7, 'FEN', 'F.7.1.1.2', 'Uzay kirliliğinin nedenlerini ifade ederek bu kirliliğin yol açabileceği olası sonuçları tahmin eder.', null, null, 'F.7.1.1', 'KAZANIM', 2, 41, null),
  ('208819f9-fd38-59dc-ad0c-8b9da905c79e', 'b6eccff7-7867-5649-a250-9d7f4848bac1', 7, 'FEN', 'F.7.1.1.3', 'Teknoloji ile uzay araştırmaları arasındaki ilişkiyi açıklar.', null, null, 'F.7.1.1', 'KAZANIM', 3, 41, null),
