insert into learning_outcomes (id, curriculum_version_id, grade, subject_code, code, title, description, theme, unit, outcome_type, sort_order, source_page, source_note) values
  ('548464dc-f4b9-5a90-8f1b-4cf81d50a49f', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.1.1', 'İletişimi etkileyen tutum ve davranışları analiz ederek kendi tutum ve davranışlarını sorgular.', null, null, 'SB.7.1', 'KAZANIM', 1, 25, null),
  ('96ce8a9a-975b-59fe-a08a-bae00f27b0b8', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.1.2', 'Bireysel ve toplumsal ilişkilerde olumlu iletişim yollarını kullanır.', null, null, 'SB.7.1', 'KAZANIM', 2, 25, null),
  ('db616fb0-ce6f-515c-b267-e7b30629ae39', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.1.3', 'Medyanın sosyal değişim ve etkileşimdeki rolünü tartışır.', null, null, 'SB.7.1', 'KAZANIM', 3, 25, null),
  ('46cf0b64-f3eb-5220-922b-7af5bf4f8353', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.1.4', 'İletişim araçlarından yararlanırken haklarını kullanır ve sorumluluklarını yerine getirir.', null, null, 'SB.7.1', 'KAZANIM', 4, 25, null),
  ('16ada84f-9fa8-5085-8f67-0f5010e2cc77', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.2.1', 'Osmanlı Devleti’nin siyasi güç olarak ortaya çıkış sürecini ve bu süreci etkileyen faktörleri açıklar.', null, null, 'SB.7.2', 'KAZANIM', 5, 25, null),
  ('11d83229-8907-5b3a-b17d-ad61f47f0f5a', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.2.2', 'Osmanlı Devleti’nin fetih siyasetini örnekler üzerinden analiz eder.', null, null, 'SB.7.2', 'KAZANIM', 6, 25, null),
  ('9e4205b9-e91e-5024-8794-7fb75ebbc5f4', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.2.3', 'Avrupa’daki gelişmelerle bağlantılı olarak Osmanlı Devleti’ni değişime zorlayan süreçleri kavrar.', null, null, 'SB.7.2', 'KAZANIM', 7, 25, null),
  ('38421b35-9648-5161-8554-b4e7303f9f2d', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.2.4', 'Osmanlı Devleti’nde ıslahat hareketleri sonucu ortaya çıkan kurumlardan hareketle toplumsal ve ekonomik değişim hakkında çıkarımlarda bulunur.', null, null, 'SB.7.2', 'KAZANIM', 8, 25, null),
  ('71e7786b-3fe0-5a97-a3c5-eddbf0886eee', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.2.5', 'Osmanlı kültür, sanat ve estetik anlayışına örnekler verir.', null, null, 'SB.7.2', 'KAZANIM', 9, 25, null),
  ('94b3ab32-6cc5-5316-9f3b-393d001c7da9', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.3.1', 'Örnek incelemeler yoluyla geçmişten günümüze, yerleşmeyi etkileyen faktörler hakkında çıkarımlarda bulunur.', null, null, 'SB.7.3', 'KAZANIM', 10, 25, null),
  ('cc04816e-cc58-5cfb-a249-5e28b1714ecd', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.3.2', 'Türkiye’de nüfusun dağılışını etkileyen faktörlerden hareketle Türkiye’nin demografik özelliklerini yorumlar.', null, null, 'SB.7.3', 'KAZANIM', 11, 26, null),
  ('4d7d4cb6-bbc2-504a-b9ba-ad121ef2c76d', '717f1f40-a9a5-5a2c-a2d6-a413e3031ee5', 7, 'SOS', 'SB.7.3.3', 'Örnek incelemeler yoluyla göçün neden ve sonuçlarını tartışır.', null, null, 'SB.7.3', 'KAZANIM', 12, 26, null),
